{
  "name": "@chalk_calliope/opencode-model-sync",
  "version": "1.1.0",
  "type": "module",
  "description": "OpenCode V2 plugin that discovers the latest models from connected OpenAI-compatible providers on server startup.",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "openai-compatible",
    "model-discovery",
    "llm"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ChalkCalliope/opencode-model-sync.git"
  },
  "homepage": "https://github.com/ChalkCalliope/opencode-model-sync#readme",
  "bugs": {
    "url": "https://github.com/ChalkCalliope/opencode-model-sync/issues"
  },
  "files": [
    "index.ts",
    "lib",
    "!lib/*.test.ts",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "devDependencies": {
    "@opencode/plugin": "2.3.0",
    "@types/bun": "^1.4.4",
    "@types/node": "^26.6.2",
    "typescript": "^7.0.2"
  }
}
